import{z as o,x as s,o as A,c as C,q as t,j as r,D as a,d as e,s as i,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"评测：RAG 三角","description":"","frontmatter":{"title":"评测：RAG 三角","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/RAG-eval-triangle.md","filePath":"llm/RAG-eval-triangle.md","lastUpdated":1791063341000}'),d={name:"llm/RAG-eval-triangle.md"};function p(F,E,m,D,h,c){const B=s("Mermaid");return A(),C("div",null,[E[2]||(E[2]=t('<h1 id="评测-rag-三角" tabindex="-1">评测：RAG 三角 <a class="header-anchor" href="#评测-rag-三角" aria-label="Permalink to &quot;评测：RAG 三角&quot;">​</a></h1><div class="epigraph"><p>端到端准确率把检索错误与阅读错误绑死在一个数字里；三角分开量，管道才知道该改哪一段。</p><footer>—— Es 等 RAGAS；Gao 等 ALCE；据 RAG 评测工程实践整理</footer></div><p><a href="/llm/rag-multimodal">上一课</a>把视觉对象接进路由，检索与生成两段的工程都铺开了。本课回答验收：链路上任何一段改动，怎么知道是变好还是变坏。「检索与生成分列」的第一性在主干<a href="/llm/rag-evaluation">RAG 评测</a>，引用归因在<a href="/llm/citation-attribution">引用与归因</a>。本课把这些收成三角加门禁：三个角、一个安全阀、一套改动必须过的流程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只报端到端准确率，归因瘫痪：换重排器后端到端没动，可能是检索本来就给对了、是生成在抄错；换嵌入涨了一点，也可能只是某类查询的波动。三角是三个角：检索质量——金标跨度覆盖与 recall@k、nDCG；忠实度——答案的断言是否被所给块支撑；答案相关性——是否答了所问。三者不同时可控：拉高 \\(k\\) 涨检索角，塞进更多块会伤忠实度（噪声块诱导编造）与相关性（注意力稀释）；重排阈值收紧，忠实度看似涨，其实是把难题以拒答的形式推出了管道。没有第四个量——拒答率——两个角的「改善」无法解读。</p><p><span class="marginnote">忠实度（faithfulness）可以理解为「不瞎编程度」：把答案拆成一句句断言，逐句检查能不能在检索到的块里找到出处，每句都有出处才得分。它衡量的是「答案与材料对不对得上」，与「答案本身好不好」无关——所以可能出现忠实度很高但答非所问的情况，这才需要另外两个角补位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>金标集：问题、金标支撑跨度（第一课协议）、金标答案三件套；切片按查询类型（标识符、改写、多跳）、语料域、难度分列。判官：忠实度与相关性用 LLM 判官打分，判官与被评系统不同族，抽人工对齐并报告一致率，分数分布随版本监控漂移。引用归因：答案逐句断言可解析到块 ID 且被该块支撑，覆盖与精确分列。门禁：换嵌入、调切分、改融合权重、换重排器、改提示，一律跑三角，分列报告，任一角显著回退即阻断发布——这是长上下文收束课「门禁」口径在 RAG 上的对应物，上线与否由三角签字，不由端到端均分签字。</p><p><span class="marginnote">为什么判官必须换族：如果拿同一个模型的近亲版本当判官，它会觉得自家行文「看起来就对」，忠实度被系统性打高——相当于让学生给自己阅卷。换一个不同家族的模型当判官，再抽几十条人工标注对齐一致率，分数才站得住。</span></p>',9)),(A(),r(n,null,{default:a(()=>[i(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHANGE%5B%22%E9%93%BE%E8%B7%AF%E6%94%B9%E5%8A%A8%22%5D%20--%3E%20GATE%5B%22%E8%B7%91%E4%B8%89%E8%A7%92%EF%BC%9A%E9%87%91%E6%A0%87%E9%9B%86%20%2B%20%E5%88%87%E7%89%87%22%5D%0A%20%20GATE%20--%3E%20RET%7B%22%E6%A3%80%E7%B4%A2%E8%A7%92%EF%BC%9A%E8%B7%A8%E5%BA%A6%E8%A6%86%E7%9B%96%20%2F%20nDCG%22%7D%0A%20%20GATE%20--%3E%20FAI%7B%22%E5%BF%A0%E5%AE%9E%E5%BA%A6%EF%BC%9A%E6%96%AD%E8%A8%80%E8%A2%AB%E5%9D%97%E6%94%AF%E6%92%91%22%7D%0A%20%20GATE%20--%3E%20REL%7B%22%E7%9B%B8%E5%85%B3%E6%80%A7%EF%BC%9A%E7%AD%94%E4%BA%86%E6%89%80%E9%97%AE%22%7D%0A%20%20RET%20--%3E%20DEC%7B%22%E4%BB%BB%E4%B8%80%E8%A7%92%E6%98%BE%E8%91%97%E5%9B%9E%E9%80%80%EF%BC%9F%22%7D%0A%20%20FAI%20--%3E%20DEC%0A%20%20REL%20--%3E%20DEC%0A%20%20DEC%20--%3E%7C%E6%98%AF%7C%20BLOCK%5B%22%E9%98%BB%E6%96%AD%E5%8F%91%E5%B8%83%EF%BC%8C%E5%9B%9E%E9%80%80%E7%89%88%E6%9C%AC%22%5D%0A%20%20DEC%20--%3E%7C%E5%90%A6%7C%20SHIP%5B%22%E6%94%BE%E8%A1%8C%EF%BC%8C%E5%88%86%E6%95%B0%E4%B8%8E%E7%89%88%E6%9C%AC%E5%AD%98%E6%A1%A3%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"三角为什么能定位层：检索角掉而其余稳，问题在召回链（切分、嵌入、索引、融合）；忠实度掉而检索角稳，问题在生成侧（提示、上下文顺序、抄写惯性）；相关性掉而忠实度稳，是检索给对了但答非所问——查询理解与改写的问题。角与角牵制的机制在预算：\\(k\\) 与上下文长度交换、重排阈值与拒答交换、块长与覆盖交换；任何「单角大涨」的改动都要查另外两角与拒答率，十有八九是代价被藏进了没报的量。判官为什么必须换族：判官与生成器同源时，模型偏爱自己的行文与结论，忠实度被系统性高估；人工对齐的对子要覆盖「部分支撑」「支撑但过时」这类边界样本，只对齐干净样本的一致率是虚高。",-1)),(A(),r(n,null,{default:a(()=>[i(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E6%9F%90%E4%B8%AA%E8%A7%92%E5%9B%9E%E9%80%80%22%5D%20--%3E%20Q1%7B%22%E6%A3%80%E7%B4%A2%E8%A7%92%E6%8E%89%E4%BA%86%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20REC%5B%22%E4%BF%AE%E5%8F%AC%E5%9B%9E%E9%93%BE%EF%BC%9A%E5%88%87%E5%88%86%20%2F%20%E5%B5%8C%E5%85%A5%20%2F%20%E7%B4%A2%E5%BC%95%20%2F%20%E8%9E%8D%E5%90%88%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E5%BF%A0%E5%AE%9E%E5%BA%A6%E6%8E%89%E4%BA%86%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20GEN%5B%22%E4%BF%AE%E7%94%9F%E6%88%90%E4%BE%A7%EF%BC%9A%E6%8F%90%E7%A4%BA%20%2F%20%E4%B8%8A%E4%B8%8B%E6%96%87%E9%A1%BA%E5%BA%8F%20%2F%20%E6%8A%84%E5%86%99%E6%83%AF%E6%80%A7%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20QRY%5B%22%E6%9F%A5%E6%9F%A5%E8%AF%A2%E7%90%86%E8%A7%A3%EF%BC%9A%E6%94%B9%E5%86%99%E4%B8%8E%E8%B7%AF%E7%94%B1%22%5D%0A%20%20REC%20--%3E%20CHK%5B%22%E5%90%8C%E6%97%B6%E6%9F%A5%E5%8F%A6%E4%B8%A4%E8%A7%92%E4%B8%8E%E6%8B%92%E7%AD%94%E7%8E%87%22%5D%0A%20%20GEN%20--%3E%20CHK%0A%20%20QRY%20--%3E%20CHK%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">数字实例：\\(k\\) 从 5 提到 20，检索角的 recall@k 可能从 0.72 涨到 0.85，但塞给生成器的上下文块翻了 4 倍——token 费用涨约 4 倍，注意力被稀释，忠实度和相关性反而可能下跌。这就是「角与角牵制」最常见的一笔账：涨的那个角是明账，跌的那两个角和账单都是暗账。</span></p><p><span class="marginnote">拒答率是安全阀不是失败项：阈值收紧后忠实度上涨，先查拒答率涨了多少——把答不了的问题推出去，三角上看不见，端到端价值却掉了。带拒答分支的评测才算数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>LLM 判官有自偏好、长度偏置与位置偏置，校准与抽检不能省，高利害域留人工复核队列。金标集会过时：语料换代后金标跨度要重新对齐，与增量更新课的版本口径联动。在线信号（点击、追问率、人工升级率）是三角的滞后代理，能发现盲区但不能替代门禁。评测集本身要防污染：金标问题混进索引会全员满分，与通用评测的污染纪律同一口径。三角立住后，下一课处理优化的钱与时间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三角分列：检索质量、忠实度、答案相关性；拒答率是解读一切的第四个量。</li><li>金标三件套：问题、支撑跨度、金标答案；按查询类型切片报。</li><li>判官换族、人工对齐覆盖边界样本；分数分布随版本监控。</li><li>改动过门禁：任一角显著回退即阻断，分数与版本一起存档。</li><li>单角大涨先查另外两角与拒答率，代价常藏在没报的量里。</li><li>出处：Es 等 RAGAS；Gao 等 ALCE；据 RAG 评测实践整理。</li></ul>',6))])}const _=o(d,[["render",p]]);export{u as __pageData,_ as default};
